A.aO7=new B.L("Edit profile","import 'package:flutter/services.dart';\nimport 'package:flutter/widgets.dart';\nimport 'package:<your_app>/ui/dashcn/foundation/gap.dart';\nimport 'package:<your_app>/ui/dashcn/theme/theme.dart';\nimport 'package:<your_app>/ui/dashcn/components/button/button.dart';\nimport 'package:<your_app>/ui/dashcn/components/input/input.dart';\nimport 'package:<your_app>/ui/dashcn/components/dialog/dialog.dart';\n\n/// Centred trigger button.\nclass _Trigger extends StatelessWidget {\n  const _Trigger({required this.label, required this.onPressed});\n\n  final String label;\n  final VoidCallback onPressed;\n\n  @override\n  Widget build(BuildContext context) {\n    return Center(\n      child: Button(\n        variant: ButtonVariant.outline,\n        size: ButtonSize.sm,\n        onPressed: onPressed,\n        child: Text(label),\n      ),\n    );\n  }\n}\n\n/// Dialog title line in the foreground token.\nWidget _title(BuildContext context, String text) {\n  final theme = Theme.of(context);\n  return Text(\n    text,\n    style: TextStyle(\n      color: theme.colors.foreground,\n      fontSize: 16,\n      fontWeight: FontWeight.w600,\n    ),\n  );\n}\n\n/// Action row: right-aligned, wraps on narrow cards.\nWidget _actions(BuildContext context, List<Widget> buttons) {\n  return Wrap(\n    alignment: WrapAlignment.end,\n    spacing: 8,\n    runSpacing: 8,\n    children: buttons,\n  );\n}\n\n/// Edit-profile form with working Save/Cancel.\nclass _EditProfileBody extends StatefulWidget {\n  const _EditProfileBody();\n\n  @override\n  State<_EditProfileBody> createState() => _EditProfileBodyState();\n}\n\nclass _EditProfileBodyState extends State<_EditProfileBody> {\n  final TextEditingController _name = TextEditingController(text: 'Ada');\n  final TextEditingController _user = TextEditingController(text: 'ada');\n\n  @override\n  void dispose() {\n    _name.dispose();\n    _user.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final gap = Theme.of(context).spacing.md;\n    return Column(\n      mainAxisSize: MainAxisSize.min,\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: <Widget>[\n        _title(context, 'Edit profile'),\n        Gap(gap),\n        Input(controller: _name, placeholder: const Text('Name')),\n        Gap(gap),\n        Input(controller: _user, placeholder: const Text('Username')),\n        Gap(gap * 2),\n        _actions(context, <Widget>[\n          Button(\n            variant: ButtonVariant.outline,\n            size: ButtonSize.sm,\n            onPressed: () => Navigator.of(context).pop(false),\n            child: const Text('Cancel'),\n          ),\n          Button(\n            size: ButtonSize.sm,\n            onPressed: () => Navigator.of(context).pop(true),\n            child: const Text('Save'),\n          ),\n        ]),\n      ],\n    );\n  }\n}\n\nWidget _editProfile(BuildContext context) => _Trigger(\n  label: 'Edit profile',\n  onPressed: () => showDialog<bool>(\n    context: context,\n    builder: (context) => const _EditProfileBody(),\n  ),\n);\n")
A.aMB=new B.L("Share link","import 'package:flutter/services.dart';\nimport 'package:flutter/widgets.dart';\nimport 'package:<your_app>/ui/dashcn/foundation/gap.dart';\nimport 'package:<your_app>/ui/dashcn/theme/theme.dart';\nimport 'package:<your_app>/ui/dashcn/components/button/button.dart';\nimport 'package:<your_app>/ui/dashcn/components/input/input.dart';\nimport 'package:<your_app>/ui/dashcn/components/dialog/dialog.dart';\n\n/// Centred trigger button.\nclass _Trigger extends StatelessWidget {\n  const _Trigger({required this.label, required this.onPressed});\n\n  final String label;\n  final VoidCallback onPressed;\n\n  @override\n  Widget build(BuildContext context) {\n    return Center(\n      child: Button(\n        variant: ButtonVariant.outline,\n        size: ButtonSize.sm,\n        onPressed: onPressed,\n        child: Text(label),\n      ),\n    );\n  }\n}\n\n/// Dialog title line in the foreground token.\nWidget _title(BuildContext context, String text) {\n  final theme = Theme.of(context);\n  return Text(\n    text,\n    style: TextStyle(\n      color: theme.colors.foreground,\n      fontSize: 16,\n      fontWeight: FontWeight.w600,\n    ),\n  );\n}\n\n/// Dialog body text in the muted token.\nWidget _body(BuildContext context, String text) {\n  return Text(\n    text,\n    style: TextStyle(color: Theme.of(context).colors.mutedForeground),\n  );\n}\n\n/// Action row: right-aligned, wraps on narrow cards.\nWidget _actions(BuildContext context, List<Widget> buttons) {\n  return Wrap(\n    alignment: WrapAlignment.end,\n    spacing: 8,\n    runSpacing: 8,\n    children: buttons,\n  );\n}\n\n/// Share link with a working copy button.\nclass _ShareBody extends StatefulWidget {\n  const _ShareBody();\n\n  @override\n  State<_ShareBody> createState() => _ShareBodyState();\n}\n\nclass _ShareBodyState extends State<_ShareBody> {\n  bool _copied = false;\n\n  Future<void> _copy() async {\n    await Clipboard.setData(\n      const ClipboardData(text: 'https://example.com/s/abc123'),\n    );\n    if (mounted) setState(() => _copied = true);\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final theme = Theme.of(context);\n    final gap = theme.spacing.md;\n    return Column(\n      mainAxisSize: MainAxisSize.min,\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: <Widget>[\n        _title(context, 'Share this document'),\n        Gap(gap),\n        _body(context, 'Anyone with the link can view.'),\n        Gap(gap),\n        DecoratedBox(\n          decoration: BoxDecoration(\n            color: theme.colors.muted,\n            borderRadius: theme.borderRadiusMd,\n            border: Border.all(color: theme.colors.border),\n          ),\n          child: Padding(\n            padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 10),\n            child: Row(\n              children: <Widget>[\n                const Flexible(child: Text('example.com/s/abc123')),\n                Gap(gap),\n                Button(\n                  variant: ButtonVariant.secondary,\n                  size: ButtonSize.sm,\n                  onPressed: _copy,\n                  child: Text(_copied ? 'Copied!' : 'Copy'),\n                ),\n              ],\n            ),\n          ),\n        ),\n        Gap(gap * 2),\n        _actions(context, <Widget>[\n          Button(\n            variant: ButtonVariant.outline,\n            size: ButtonSize.sm,\n            onPressed: () => Navigator.of(context).pop(),\n            child: const Text('Close'),\n          ),\n        ]),\n      ],\n    );\n  }\n}\n\nWidget _share(BuildContext context) => _Trigger(\n  label: 'Share link',\n  onPressed: () =>\n      showDialog<void>(context: context, builder: (_) => const _ShareBody()),\n);\n")
A.aMg=new B.L("Invite members","import 'package:flutter/services.dart';\nimport 'package:flutter/widgets.dart';\nimport 'package:<your_app>/ui/dashcn/foundation/gap.dart';\nimport 'package:<your_app>/ui/dashcn/theme/theme.dart';\nimport 'package:<your_app>/ui/dashcn/components/button/button.dart';\nimport 'package:<your_app>/ui/dashcn/components/input/input.dart';\nimport 'package:<your_app>/ui/dashcn/components/dialog/dialog.dart';\n\n/// Centred trigger button.\nclass _Trigger extends StatelessWidget {\n  const _Trigger({required this.label, required this.onPressed});\n\n  final String label;\n  final VoidCallback onPressed;\n\n  @override\n  Widget build(BuildContext context) {\n    return Center(\n      child: Button(\n        variant: ButtonVariant.outline,\n        size: ButtonSize.sm,\n        onPressed: onPressed,\n        child: Text(label),\n      ),\n    );\n  }\n}\n\n/// Dialog title line in the foreground token.\nWidget _title(BuildContext context, String text) {\n  final theme = Theme.of(context);\n  return Text(\n    text,\n    style: TextStyle(\n      color: theme.colors.foreground,\n      fontSize: 16,\n      fontWeight: FontWeight.w600,\n    ),\n  );\n}\n\n/// Action row: right-aligned, wraps on narrow cards.\nWidget _actions(BuildContext context, List<Widget> buttons) {\n  return Wrap(\n    alignment: WrapAlignment.end,\n    spacing: 8,\n    runSpacing: 8,\n    children: buttons,\n  );\n}\n\n/// Invite team members with a working list.\nclass _InviteBody extends StatefulWidget {\n  const _InviteBody();\n\n  @override\n  State<_InviteBody> createState() => _InviteBodyState();\n}\n\nclass _InviteBodyState extends State<_InviteBody> {\n  final TextEditingController _email = TextEditingController();\n  final List<String> _invited = <String>['ada@example.com'];\n\n  @override\n  void dispose() {\n    _email.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final gap = Theme.of(context).spacing.md;\n    return Column(\n      mainAxisSize: MainAxisSize.min,\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: <Widget>[\n        _title(context, 'Invite members'),\n        Gap(gap),\n        Row(\n          children: <Widget>[\n            Flexible(\n              child: Input(controller: _email, hintText: 'Email'),\n            ),\n            Gap(gap),\n            Button(\n              size: ButtonSize.sm,\n              onPressed: () {\n                final String value = _email.text.trim();\n                if (value.isEmpty) return;\n                setState(() {\n                  _invited.add(value);\n                  _email.clear();\n                });\n              },\n              child: const Text('Invite'),\n            ),\n          ],\n        ),\n        Gap(gap),\n        for (final String address in _invited) Text(address),\n        Gap(gap * 2),\n        _actions(context, <Widget>[\n          Button(\n            variant: ButtonVariant.outline,\n            size: ButtonSize.sm,\n            onPressed: () => Navigator.of(context).pop(),\n            child: const Text('Done'),\n          ),\n        ]),\n      ],\n    );\n  }\n}\n\nWidget _invite(BuildContext context) => _Trigger(\n  label: 'Invite members',\n  onPressed: () =>\n      showDialog<void>(context: context, builder: (_) => const _InviteBody()),\n);\n")
A.aNk=new B.L("Terms","import 'package:flutter/services.dart';\nimport 'package:flutter/widgets.dart';\nimport 'package:<your_app>/ui/dashcn/foundation/gap.dart';\nimport 'package:<your_app>/ui/dashcn/theme/theme.dart';\nimport 'package:<your_app>/ui/dashcn/components/button/button.dart';\nimport 'package:<your_app>/ui/dashcn/components/input/input.dart';\nimport 'package:<your_app>/ui/dashcn/components/dialog/dialog.dart';\n\n/// Centred trigger button.\nclass _Trigger extends StatelessWidget {\n  const _Trigger({required this.label, required this.onPressed});\n\n  final String label;\n  final VoidCallback onPressed;\n\n  @override\n  Widget build(BuildContext context) {\n    return Center(\n      child: Button(\n        variant: ButtonVariant.outline,\n        size: ButtonSize.sm,\n        onPressed: onPressed,\n        child: Text(label),\n      ),\n    );\n  }\n}\n\n/// Dialog title line in the foreground token.\nWidget _title(BuildContext context, String text) {\n  final theme = Theme.of(context);\n  return Text(\n    text,\n    style: TextStyle(\n      color: theme.colors.foreground,\n      fontSize: 16,\n      fontWeight: FontWeight.w600,\n    ),\n  );\n}\n\n/// Dialog body text in the muted token.\nWidget _body(BuildContext context, String text) {\n  return Text(\n    text,\n    style: TextStyle(color: Theme.of(context).colors.mutedForeground),\n  );\n}\n\n/// Action row: right-aligned, wraps on narrow cards.\nWidget _actions(BuildContext context, List<Widget> buttons) {\n  return Wrap(\n    alignment: WrapAlignment.end,\n    spacing: 8,\n    runSpacing: 8,\n    children: buttons,\n  );\n}\n\n/// Scrollable terms with explicit Accept/Decline.\nWidget _termsBody(BuildContext context) {\n  final gap = Theme.of(context).spacing.md;\n  return Column(\n    mainAxisSize: MainAxisSize.min,\n    crossAxisAlignment: CrossAxisAlignment.stretch,\n    children: <Widget>[\n      _title(context, 'Terms of service'),\n      Gap(gap),\n      ConstrainedBox(\n        constraints: const BoxConstraints(maxHeight: 220),\n        child: SingleChildScrollView(\n          child: _body(\n            context,\n            '1. Be kind.\\n\\n2. Ship working software.\\n\\n'\n            '3. Respect the theme tokens.\\n\\n4. Prefer composition.\\n\\n'\n            '5. Test what you ship.\\n\\n6. Document the contract.',\n          ),\n        ),\n      ),\n      Gap(gap * 2),\n      _actions(context, <Widget>[\n        Button(\n          variant: ButtonVariant.outline,\n          size: ButtonSize.sm,\n          onPressed: () => Navigator.of(context).pop(false),\n          child: const Text('Decline'),\n        ),\n        Button(\n          size: ButtonSize.sm,\n          onPressed: () => Navigator.of(context).pop(true),\n          child: const Text('Accept'),\n        ),\n      ]),\n    ],\n  );\n}\n\nWidget _terms(BuildContext context) => _Trigger(\n  label: 'Read terms',\n  onPressed: () => showDialog<bool>(\n    context: context,\n    builder: (context) => _termsBody(context),\n  ),\n);\n")
A.aPw=new B.L("Picker","import 'package:flutter/services.dart';\nimport 'package:flutter/widgets.dart';\nimport 'package:<your_app>/ui/dashcn/foundation/gap.dart';\nimport 'package:<your_app>/ui/dashcn/theme/theme.dart';\nimport 'package:<your_app>/ui/dashcn/components/button/button.dart';\nimport 'package:<your_app>/ui/dashcn/components/input/input.dart';\nimport 'package:<your_app>/ui/dashcn/components/dialog/dialog.dart';\n\n/// Centred trigger button.\nclass _Trigger extends StatelessWidget {\n  const _Trigger({required this.label, required this.onPressed});\n\n  final String label;\n  final VoidCallback onPressed;\n\n  @override\n  Widget build(BuildContext context) {\n    return Center(\n      child: Button(\n        variant: ButtonVariant.outline,\n        size: ButtonSize.sm,\n        onPressed: onPressed,\n        child: Text(label),\n      ),\n    );\n  }\n}\n\n/// Dialog title line in the foreground token.\nWidget _title(BuildContext context, String text) {\n  final theme = Theme.of(context);\n  return Text(\n    text,\n    style: TextStyle(\n      color: theme.colors.foreground,\n      fontSize: 16,\n      fontWeight: FontWeight.w600,\n    ),\n  );\n}\n\n/// Dialog body text in the muted token.\nWidget _body(BuildContext context, String text) {\n  return Text(\n    text,\n    style: TextStyle(color: Theme.of(context).colors.mutedForeground),\n  );\n}\n\n/// Command-like picker with a working filter.\nclass _PickerBody extends StatefulWidget {\n  const _PickerBody();\n\n  @override\n  State<_PickerBody> createState() => _PickerBodyState();\n}\n\nclass _PickerBodyState extends State<_PickerBody> {\n  final TextEditingController _query = TextEditingController();\n  String _filter = '';\n\n  static const List<String> _items = <String>[\n    'Calendar',\n    'Search Emoji',\n    'Calculator',\n    'Activity',\n  ];\n\n  @override\n  void initState() {\n    super.initState();\n    _query.addListener(() => setState(() => _filter = _query.text));\n  }\n\n  @override\n  void dispose() {\n    _query.dispose();\n    super.dispose();\n  }\n\n  @override\n  Widget build(BuildContext context) {\n    final gap = Theme.of(context).spacing.md;\n    final List<String> shown = _items\n        .where(\n          (String item) => item.toLowerCase().contains(_filter.toLowerCase()),\n        )\n        .toList();\n    return Column(\n      mainAxisSize: MainAxisSize.min,\n      crossAxisAlignment: CrossAxisAlignment.stretch,\n      children: <Widget>[\n        _title(context, 'Jump to\u2026'),\n        Gap(gap),\n        Input(controller: _query, hintText: 'Type to filter'),\n        Gap(gap),\n        for (final String item in shown)\n          Button(\n            variant: ButtonVariant.ghost,\n            size: ButtonSize.sm,\n            onPressed: () => Navigator.of(context).pop(item),\n            child: Align(\n              alignment: AlignmentDirectional.centerStart,\n              child: Text(item),\n            ),\n          ),\n        if (shown.isEmpty) _body(context, 'No matches.'),\n      ],\n    );\n  }\n}\n\nWidget _picker(BuildContext context) => _Trigger(\n  label: 'Open picker',\n  onPressed: () =>\n      showDialog<String>(context: context, builder: (_) => const _PickerBody()),\n);\n")
A.aPt=new B.L("Barrier locked","import 'package:flutter/services.dart';\nimport 'package:flutter/widgets.dart';\nimport 'package:<your_app>/ui/dashcn/foundation/gap.dart';\nimport 'package:<your_app>/ui/dashcn/theme/theme.dart';\nimport 'package:<your_app>/ui/dashcn/components/button/button.dart';\nimport 'package:<your_app>/ui/dashcn/components/input/input.dart';\nimport 'package:<your_app>/ui/dashcn/components/dialog/dialog.dart';\n\n/// Centred trigger button.\nclass _Trigger extends StatelessWidget {\n  const _Trigger({required this.label, required this.onPressed});\n\n  final String label;\n  final VoidCallback onPressed;\n\n  @override\n  Widget build(BuildContext context) {\n    return Center(\n      child: Button(\n        variant: ButtonVariant.outline,\n        size: ButtonSize.sm,\n        onPressed: onPressed,\n        child: Text(label),\n      ),\n    );\n  }\n}\n\n/// Dialog title line in the foreground token.\nWidget _title(BuildContext context, String text) {\n  final theme = Theme.of(context);\n  return Text(\n    text,\n    style: TextStyle(\n      color: theme.colors.foreground,\n      fontSize: 16,\n      fontWeight: FontWeight.w600,\n    ),\n  );\n}\n\n/// Dialog body text in the muted token.\nWidget _body(BuildContext context, String text) {\n  return Text(\n    text,\n    style: TextStyle(color: Theme.of(context).colors.mutedForeground),\n  );\n}\n\n/// Action row: right-aligned, wraps on narrow cards.\nWidget _actions(BuildContext context, List<Widget> buttons) {\n  return Wrap(\n    alignment: WrapAlignment.end,\n    spacing: 8,\n    runSpacing: 8,\n    children: buttons,\n  );\n}\n\n/// Barrier-locked dialog with an explicit Cancel way out (never traps).\nWidget _lockedBody(BuildContext context) {\n  final gap = Theme.of(context).spacing.md;\n  return Column(\n    mainAxisSize: MainAxisSize.min,\n    crossAxisAlignment: CrossAxisAlignment.stretch,\n    children: <Widget>[\n      _title(context, 'Delete this project?'),\n      Gap(gap),\n      _body(\n        context,\n        'The barrier is locked: tap outside or press Escape does nothing. '\n        'Use Cancel or Delete to leave.',\n      ),\n      Gap(gap * 2),\n      _actions(context, <Widget>[\n        Button(\n          variant: ButtonVariant.outline,\n          size: ButtonSize.sm,\n          onPressed: () => Navigator.of(context).pop(false),\n          child: const Text('Cancel'),\n        ),\n        Button(\n          variant: ButtonVariant.destructive,\n          size: ButtonSize.sm,\n          onPressed: () => Navigator.of(context).pop(true),\n          child: const Text('Delete'),\n        ),\n      ]),\n    ],\n  );\n}\n\nWidget _locked(BuildContext context) => _Trigger(\n  label: 'Open locked dialog',\n  onPressed: () => showDialog<bool>(\n    context: context,\n    barrierDismissible: false,\n    builder: (context) => _lockedBody(context),\n  ),\n);\n")
